function solve(points, k) {
  if (k <= 0) return [];
  const square = (p) => {
    let total = 0;
    for (let i = 0; i < p.length; i++) total += p[i] * p[i];
    return total;
  };
  const rank = (a, b) => {
    const da = square(a);
    const db = square(b);
    if (da !== db) return da - db;
    const shared = Math.min(a.length, b.length);
    for (let i = 0; i < shared; i++) {
      if (a[i] !== b[i]) return a[i] - b[i];
    }
    return a.length - b.length;
  };
  const heap = [];
  const swap = (i, j) => {
    const held = heap[i];
    heap[i] = heap[j];
    heap[j] = held;
  };
  const siftUp = (i) => {
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (rank(heap[parent], heap[i]) >= 0) break;
      swap(parent, i);
      i = parent;
    }
  };
  const siftDown = (i) => {
    for (;;) {
      let worst = i;
      const left = 2 * i + 1;
      const right = left + 1;
      if (left < heap.length && rank(heap[left], heap[worst]) > 0) worst = left;
      if (right < heap.length && rank(heap[right], heap[worst]) > 0) worst = right;
      if (worst === i) break;
      swap(i, worst);
      i = worst;
    }
  };
  for (let i = 0; i < points.length; i++) {
    heap.push(points[i]);
    siftUp(heap.length - 1);
    if (heap.length > k) {
      const last = heap.pop();
      if (heap.length > 0) {
        heap[0] = last;
        siftDown(0);
      }
    }
  }
  heap.sort(rank);
  return heap;
}
